/**
 * @suppress
 */
public object FfiConverterTypeMobileCore: FfiConverter<MobileCore, Long> {
    override fun lower(value: MobileCore): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): MobileCore {
        return MobileCore(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): MobileCore {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: MobileCore) = 8UL

    override fun write(value: MobileCore, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



